// Fuzz stub for: template <typename V, typename Extractor, typename K = typename std::invoke_result_t<Extractor, V const&>>
// std::map<K, std::vector<V>> split(std::vector<V> const& data, Extractor extractor)
// We instantiate with V=int and an int-returning lambda Extractor; K deduces to int.
{
    // Generate bounded-size input data vector without looping over FUZZ_PARAM for scalars.
    // Use an array macro to get diverse elements, then take the first n entries.
    const unsigned int raw_n = *FUZZ_PARAM(unsigned int);
    const size_t n = (size_t)(raw_n % 64u); // keep allocations small
    auto arr_ptr = FUZZ_PARAM(int[64]);     // const int (*)[64]

    std::vector<int> data;
    data.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        data.push_back((*arr_ptr)[i]);
    }

    // Build an extractor with several fuzzed knobs while ensuring well-defined behavior.
    // - base for modulo is in [1, 16] to avoid div-by-zero and keep key-space small
    // - shift is in [0, 3]
    // - mask and add are arbitrary ints
    unsigned int base = (*FUZZ_PARAM(unsigned int) % 16u) + 1u; // enforce >=1
    unsigned int shift = (*FUZZ_PARAM(unsigned int) & 3u);
    int mask = *FUZZ_PARAM(int);
    int add = *FUZZ_PARAM(int);

    auto extractor = [=](int const &v) -> int {
        // Key computation purposefully mixes bits but remains fast and total.
        // Use modulo base to create collisions and exercise multiple buckets.
        int mixed = ((v + add) ^ mask);
        int shifted = (shift == 0 ? mixed : (mixed >> shift));
        int key = (base == 0 ? shifted : (shifted % (int)base)); // base is never 0, guard remains for clarity
        return key;
    };

    try {
        // Invoke target function
        auto result = split<int, decltype(extractor)>(data, extractor);

        // Property checks that should always hold for a correct implementation:
        // 1) Total number of elements across all buckets equals input size.
        size_t total = 0;
        for (const auto &kv : result) { total += kv.second.size(); }
        FUZZ_ASSERT(total == data.size(), "Total elements across buckets must equal input size");

        // 2) Every input element appears in exactly one bucket corresponding to extractor(v).
        // Because elements are copied, we check presence-by-value in the mapped vector.
        for (const int &v : data) {
            int k = extractor(v);
            auto it = result.find(k);
            FUZZ_ASSERT(it != result.end(), "Key for element must exist in result map");
            bool found = false;
            for (const int &vv : it->second) { if (vv == v) { found = true; break; } }
            FUZZ_ASSERT(found, "Element must appear in the vector for its computed key");
        }
    } catch (...) {
        // The API allows exceptions from allocations, copies, or extractor.
        // Treat any thrown exception as an error path to explore; bail cleanly.
        FUZZ_BAIL();
    }

    // Validation summary: This stub constructs a bounded std::vector<int>, applies a fuzz-configured
    // extractor that deterministically maps ints to small int keys, invokes split, and asserts core invariants
    // about element accounting and correct grouping. No inputs/outputs are retained across calls.
}
